insert into publishers (name) values ('Microsoft') on conflict (name) do nothing; insert into tools (name, slug, publisher_id, summary, description, official_url, status, pricing_model, price_display, api_available, open_source, local_available, keywords, strengths, limits, audience, last_verified_at) select 'Microsoft Copilot', 'microsoft-copilot', p.id, 'Microsoft''s AI assistant across Windows, Edge, Microsoft 365 and Bing.', 'Copilot helps with writing, research, coding and productivity inside Microsoft products and on the web.', 'https://copilot.microsoft.com', 'published', 'Freemium', 'Free / Copilot Pro', true, false, false, ARRAY['assistant', 'microsoft', 'bing']::text[], ARRAY['Deep Microsoft 365 integration', 'Web grounding']::text[], ARRAY['Feature set varies by plan and product']::text[], ARRAY['Professionals', 'Students']::text[], current_date from publishers p where p.name = 'Microsoft' on conflict (slug) do nothing;
insert into publishers (name) values ('Meta') on conflict (name) do nothing; insert into tools (name, slug, publisher_id, summary, description, official_url, status, pricing_model, price_display, api_available, open_source, local_available, keywords, strengths, limits, audience, last_verified_at) select 'Meta AI', 'meta-ai', p.id, 'Meta''s consumer AI assistant powered by Llama models across Meta apps.', 'Meta AI is available in WhatsApp, Messenger, Instagram and on the web for chat, image generation and search-style answers.', 'https://www.meta.ai', 'published', 'Free', 'Free', false, false, false, ARRAY['meta', 'llama', 'assistant']::text[], ARRAY['Free access', 'Integrated in Meta apps']::text[], ARRAY['Availability varies by country']::text[], ARRAY['Consumers']::text[], current_date from publishers p where p.name = 'Meta' on conflict (slug) do nothing;
