insert into publishers (name) values ('Quora') on conflict (name) do nothing; insert into tools (name, slug, publisher_id, summary, description, official_url, status, pricing_model, price_display, api_available, open_source, local_available, keywords, strengths, limits, audience, last_verified_at) select 'Poe', 'poe', p.id, 'Multi-bot chat platform aggregating many AI models in one app.', 'Poe by Quora provides access to multiple third-party and custom bots with a shared chat interface and subscriptions.', 'https://poe.com', 'published', 'Freemium', 'Free / Poe subscription', true, false, false, ARRAY['multi-model', 'bots', 'quora']::text[], ARRAY['Many models in one place', 'Bot creation']::text[], ARRAY['Usage limits depend on subscription']::text[], ARRAY['Power users', 'Developers']::text[], current_date from publishers p where p.name = 'Quora' on conflict (slug) do nothing;